// Figma Design Review — "push as native layers" plugin.
// Generated by the board for one design. Import once in Figma Desktop
// (Plugins → Development → Import plugin from manifest…) and run it inside the target file.
// It rebuilds every element of the design as real, editable Figma nodes.
/* eslint-disable */
const DESIGN = __DESIGN__;

const FAMILY = 'Inter';
const WEIGHT_STYLE = {100: 'Thin', 200: 'Extra Light', 300: 'Light', 400: 'Regular', 500: 'Medium', 600: 'Semi Bold', 700: 'Bold', 800: 'Extra Bold', 900: 'Black'};
const fontCache = {};

function parseColor(c) {
  if (!c) return null;
  c = String(c).trim();
  if (!c || c === 'none' || c === 'transparent') return null;
  let m = c.match(/^#([0-9a-f]{3,8})$/i);
  if (m) {
    let h = m[1];
    if (h.length === 3 || h.length === 4) h = h.split('').map(x => x + x).join('');
    if (h.length !== 6 && h.length !== 8) return null;
    const n = parseInt(h, 16);
    const a = h.length === 8 ? (n & 255) / 255 : 1;
    const v = h.length === 8 ? n >>> 8 : n;
    return {r: ((v >> 16) & 255) / 255, g: ((v >> 8) & 255) / 255, b: (v & 255) / 255, a};
  }
  m = c.match(/^rgba?\(([^)]+)\)$/i);
  if (m) {
    const p = m[1].split(',').map(s => parseFloat(s));
    return {r: (p[0] || 0) / 255, g: (p[1] || 0) / 255, b: (p[2] || 0) / 255, a: p.length > 3 ? p[3] : 1};
  }
  return null;
}
function solid(c) {
  const k = parseColor(c);
  if (!k) return [];
  return [{type: 'SOLID', color: {r: k.r, g: k.g, b: k.b}, opacity: k.a}];
}
async function font(weight) {
  const style = WEIGHT_STYLE[Math.round((weight || 400) / 100) * 100] || 'Regular';
  const tries = [style, 'Regular'];
  for (const s of tries) {
    const key = FAMILY + '/' + s;
    if (fontCache[key] === true) return {family: FAMILY, style: s};
    if (fontCache[key] === false) continue;
    try { await figma.loadFontAsync({family: FAMILY, style: s}); fontCache[key] = true; return {family: FAMILY, style: s}; }
    catch (e) { fontCache[key] = false; }
  }
  await figma.loadFontAsync({family: 'Inter', style: 'Regular'});
  return {family: 'Inter', style: 'Regular'};
}
function label(e) {
  if (e.type === 'text') return (String(e.text || '').split('\n')[0] || 'Text').slice(0, 40);
  return {rect: 'Rectangle', ellipse: 'Ellipse', line: 'Line', image: 'Image'}[e.type] || e.type;
}
function dataUrlBytes(href) {
  const m = String(href || '').match(/^data:([^;,]+)?(;base64)?,(.*)$/s);
  if (!m) return null;
  if (m[2]) return figma.base64Decode(m[3]);
  return new TextEncoder().encode(decodeURIComponent(m[3]));
}

async function buildElement(e, parent) {
  const w = Math.max(0.01, Number(e.w) || 0), h = Math.max(0.01, Number(e.h) || 0);
  let n = null;
  if (e.type === 'rect') {
    n = figma.createRectangle();
    n.resize(w, h); n.x = e.x; n.y = e.y;
    n.fills = solid(e.fill);
    n.strokes = solid(e.stroke); if (e.stroke && parseColor(e.stroke)) n.strokeWeight = Number(e.sw) || 1;
    n.strokeAlign = 'CENTER';
    if (e.r) n.cornerRadius = Number(e.r) || 0;
  } else if (e.type === 'ellipse') {
    n = figma.createEllipse();
    n.resize(w, h); n.x = e.x; n.y = e.y;
    n.fills = solid(e.fill);
    n.strokes = solid(e.stroke); if (e.stroke && parseColor(e.stroke)) n.strokeWeight = Number(e.sw) || 1;
  } else if (e.type === 'line') {
    const dx = Number(e.w) || 0, dy = Number(e.h) || 0;
    const len = Math.max(0.01, Math.hypot(dx, dy));
    n = figma.createLine();
    n.resize(len, 0);
    n.x = e.x; n.y = e.y;
    n.rotation = -Math.atan2(dy, dx) * 180 / Math.PI;
    n.strokes = solid(e.stroke || '#111111');
    n.strokeWeight = Number(e.sw) || 1;
    n.strokeCap = 'ROUND';
  } else if (e.type === 'text') {
    const str = String(e.text == null ? '' : e.text);
    if (!str.trim()) return null;
    n = figma.createText();
    const fn = await font(e.fw);
    n.fontName = fn;
    n.characters = str;
    const fs = Math.max(1, Number(e.fs) || 16);
    n.fontSize = fs;
    n.lineHeight = {value: 125, unit: 'PERCENT'};
    n.textAlignHorizontal = e.align === 'center' ? 'CENTER' : e.align === 'right' ? 'RIGHT' : 'LEFT';
    n.textAlignVertical = 'TOP';
    n.fills = solid(e.fill || '#111111');
    // the board draws text with a hanging baseline at y; Figma centres the glyphs in a 125% line box
    const yoff = fs * 0.125;
    if (str.indexOf('\n') === -1) {
      n.textAutoResize = 'WIDTH_AND_HEIGHT';
      const ax = e.align === 'center' ? e.x + w / 2 : e.align === 'right' ? e.x + w : e.x;
      n.x = e.align === 'center' ? ax - n.width / 2 : e.align === 'right' ? ax - n.width : ax;
    } else {
      n.textAutoResize = 'HEIGHT';
      n.resize(Math.max(1, w), n.height);
      n.x = e.x;
    }
    n.y = e.y - yoff;
  } else if (e.type === 'image') {
    n = figma.createRectangle();
    n.resize(w, h); n.x = e.x; n.y = e.y;
    let done = false;
    try {
      const bytes = dataUrlBytes(e.href);
      if (bytes) { const img = figma.createImage(bytes); n.fills = [{type: 'IMAGE', scaleMode: 'FILL', imageHash: img.hash}]; done = true; }
    } catch (err) {}
    if (!done) n.fills = solid('#d9d9d9');
  } else {
    return null;
  }
  n.name = label(e);
  if (e.opacity != null && e.opacity !== 1) n.opacity = Math.max(0, Math.min(1, Number(e.opacity)));
  parent.appendChild(n);
  return n;
}

async function pageOf(node) {
  let p = node;
  while (p && p.type !== 'PAGE') p = p.parent;
  return p;
}

async function placeFrame(frame, spec, cursor) {
  // Next to the original Figma frame when this design was drawn on one and that frame is in this file;
  // otherwise in the middle of the current view.
  let orig = null;
  if (spec.node_id) { try { orig = await figma.getNodeByIdAsync(spec.node_id); } catch (e) { orig = null; } }
  if (orig && orig.parent && 'x' in orig) {
    const page = await pageOf(orig);
    if (page && page.id !== figma.currentPage.id) { try { await figma.setCurrentPageAsync(page); } catch (e) {} }
    orig.parent.appendChild(frame);
    frame.x = orig.x + orig.width + 80 + cursor.dx;
    frame.y = orig.y;
    cursor.dx += frame.width + 80;
    return 'beside';
  }
  figma.currentPage.appendChild(frame);
  const c = figma.viewport.center;
  frame.x = Math.round(c.x - frame.width / 2 + cursor.dx);
  frame.y = Math.round(c.y - frame.height / 2);
  cursor.dx += frame.width + 80;
  return 'viewport';
}

async function run() {
  const created = [];
  const cursor = {dx: 0};
  let elements = 0, skipped = 0, beside = 0;
  for (const spec of DESIGN.frames) {
    const frame = figma.createFrame();
    frame.name = spec.name || 'Frame';
    frame.resize(Math.max(1, spec.width || 100), Math.max(1, spec.height || 100));
    frame.clipsContent = true;
    frame.fills = spec.kind === 'local' ? solid(spec.bg || '#ffffff') : [];
    const where = await placeFrame(frame, spec, cursor);
    if (where === 'beside') beside++;
    for (const e of spec.els || []) {
      try { const n = await buildElement(e, frame); if (n) elements++; else skipped++; }
      catch (err) { skipped++; console.warn('skipped element', e && e.id, err); }
    }
    created.push(frame);
  }
  if (created.length) {
    figma.currentPage.selection = created;
    figma.viewport.scrollAndZoomIntoView(created);
  }
  const what = created.length === 1 ? 'frame "' + created[0].name + '"' : created.length + ' frames';
  figma.notify('Built ' + what + ' — ' + elements + ' editable layers' + (beside ? ', placed next to the original' : '') + (skipped ? ' (' + skipped + ' skipped)' : '') + '. From ' + (DESIGN.app || 'Figma Design Review') + '.', {timeout: 6000});
  figma.closePlugin();
}

run().catch(err => {
  console.error(err);
  figma.notify('Design Review push failed: ' + (err && err.message ? err.message : err), {error: true, timeout: 8000});
  figma.closePlugin();
});